const definitions=[
 ['color.palette.carrot-600','브랜드 오렌지','color','#ff6600','#e65200','brand','Brand'],
 ['color.palette.carrot-700','진한 브랜드 오렌지','color','#e14d00','#ff6600',null,'Brand'],
 ['color.palette.carrot-100','부드러운 브랜드 배경','color','#fff2ec','#31241f','weak','Brand'],
 ['color.palette.gray-00','기본 표면','color','#ffffff','#000000',null,'Neutral'],
 ['color.palette.gray-100','다크 기본 표면','color','#f7f8f9','#16171b',null,'Neutral'],
 ['color.palette.gray-200','캔버스 배경','color','#f3f4f5','#1d2025','page','Neutral'],
 ['color.palette.gray-400','경계선','color','#dcdee3','#393d46','line','Neutral'],
 ['color.palette.gray-800','보조 텍스트','color','#555d6d','#dcdee3','muted','Neutral'],
 ['color.palette.gray-1000','기본 텍스트','color','#1a1c20','#f3f4f5','ink','Neutral'],
 ['color.palette.green-700','긍정 상태','color','#079171','#22b27f','positive','Status'],
 ['color.palette.red-700','오류 상태','color','#fa342c','#ff6e60','critical','Status'],
 ['color.palette.blue-700','정보 상태','color','#217cf9','#41a2f9','info','Status'],
 ['studio.spacing.card-gap','카드 사이 간격','spacing',16,16,'gap','Layout',0,48],
 ['studio.spacing.card-padding','카드 내부 여백','spacing',20,20,'padding','Layout',8,40],
 ['studio.radius.card','카드 모서리','borderRadius',16,16,'radius','Shape',0,40],
 ['studio.radius.control','버튼과 배지 모서리','borderRadius',8,8,'button-radius','Shape',0,24],
 ['studio.fontSize.body','본문 크기','fontSizes',13,13,'font','Typography',11,20],
 ['studio.fontSize.heading','대시보드 제목 크기','fontSizes',22,22,'title','Typography',16,32],
 ['studio.fontWeight.heading','제목 두께','fontWeights',700,700,'weight','Typography',400,900]
];
const categories=[['color','◉','Color','브랜드의 인상을 만드는 색상'],['spacing','⊞','Spacing','화면에 리듬을 만드는 간격'],['borderRadius','▢','Radius','컴포넌트의 형태를 만드는 곡률'],['type','T','Typography','정보의 위계를 만드는 타이포그래피']];
const storageKey='seed-token-studio-v1';let category='color',mode='light',history=[],exportText='';
const defaults=()=>Object.fromEntries(['light','dark'].map((m,i)=>[m,Object.fromEntries(definitions.map(d=>[d[0],d[3+i]]))]));let values=defaults();
function valid(d,v){return d[2]==='color'?typeof v==='string'&&/^#[0-9a-f]{6}$/i.test(v):typeof v==='number'&&Number.isFinite(v)&&v>=d[7]&&v<=d[8]&&(d[2]!=='fontWeights'||v%100===0)}
try{const saved=JSON.parse(localStorage.getItem(storageKey));for(const m of ['light','dark'])for(const d of definitions)if(saved?.[m]&&valid(d,saved[m][d[0]]))values[m][d[0]]=saved[m][d[0]]}catch{}
const $=id=>document.getElementById(id);function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2500)}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(values));$('save-state').textContent='● 브라우저에 저장됨'}catch{$('save-state').textContent='저장 불가 · JSON으로 보관하세요'}$('undo').disabled=!history.length}
function matches(d){return category==='type'?['fontSizes','fontWeights'].includes(d[2]):d[2]===category}
function renderNav(){ $('categories').innerHTML=categories.map(c=>`<button data-category="${c[0]}" class="${category===c[0]?'active':''}"><span class="nav-symbol">${c[1]}</span>${c[2]}<small>${definitions.filter(d=>c[0]==='type'?['fontSizes','fontWeights'].includes(d[2]):d[2]===c[0]).length}</small></button>`).join('');}
function renderTokens(){const c=categories.find(c=>c[0]===category);$('category-title').textContent=c[2];$('category-desc').textContent=c[3];const query=$('search').value.toLowerCase();const filtered=definitions.filter(d=>matches(d)&&(!query||`${d[0]} ${d[1]}`.toLowerCase().includes(query)));$('token-count').textContent=`${filtered.length} tokens`;$('result-label').textContent=`${mode.toUpperCase()} · DESIGN TOKENS`;let group='';$('token-list').innerHTML=filtered.map(d=>{const v=values[mode][d[0]],changed=v!==d[mode==='light'?3:4];let title='';if(group!==d[6]){group=d[6];title=`<div class="group-label">${group}</div>`}return `${title}<div class="token-row" data-name="${d[0]}"><div class="token-top"><span>${d[1]} <span class="changed-dot">${changed?'●':''}</span></span><button class="token-reset" title="이 토큰 초기화" style="border:0;padding:0;color:#aaa">↶</button></div><div class="token-value">${d[2]==='color'?`<input type="color" value="${v}" aria-label="${d[1]} 색상">`:`<input type="range" min="${d[7]}" max="${d[8]}" step="${d[2]==='fontWeights'?100:1}" value="${v}" aria-label="${d[1]} 슬라이더">`}<input class="value-text" ${d[2]==='color'?'type="text" maxlength="7"':'type="number" min="'+d[7]+'" max="'+d[8]+'" step="'+(d[2]==='fontWeights'?100:1)+'"'} value="${v}" aria-label="${d[1]} 값">${d[2]!=='color'&&d[2]!=='fontWeights'?'<span class="unit">px</span>':''}</div><div class="alias">${d[0]}</div></div>`}).join('')||'<div class="empty">검색 결과가 없습니다.</div>';}
function apply(){const dash=$('dashboard');for(const d of definitions){if(d[5])dash.style.setProperty('--'+d[5],values[mode][d[0]]+(d[2]!=='color'&&d[2]!=='fontWeights'?'px':''))}dash.style.setProperty('--brand',values[mode][mode==='light'?'color.palette.carrot-600':'color.palette.carrot-700']);dash.style.setProperty('--surface',values[mode][mode==='light'?'color.palette.gray-00':'color.palette.gray-100']);let count=0;for(const m of ['light','dark'])for(const d of definitions)if(values[m][d[0]]!==d[m==='light'?3:4])count++;$('changed-count').textContent=`변경된 토큰 ${count}개`;persist()}
function update(name,v){const d=definitions.find(d=>d[0]===name);if(!valid(d,v)||v===values[mode][name])return;history.push(JSON.stringify(values));if(history.length>100)history.shift();values[mode][name]=v;apply();const row=[...document.querySelectorAll('.token-row')].find(r=>r.dataset.name===name);if(row){row.querySelector('.changed-dot').textContent=v!==d[mode==='light'?3:4]?'●':'';for(const input of row.querySelectorAll('input'))if(input!==document.activeElement)input.value=v}}
$('token-list').addEventListener('input',e=>{if(e.target.tagName!=='INPUT')return;const row=e.target.closest('.token-row');const d=definitions.find(d=>d[0]===row.dataset.name);const v=d[2]==='color'?e.target.value.toLowerCase():e.target.value===''?NaN:Number(e.target.value);e.target.setAttribute('aria-invalid',String(!valid(d,v)));if(valid(d,v))update(d[0],v)});
$('token-list').addEventListener('focusout',e=>{if(e.target.tagName==='INPUT'){const row=e.target.closest('.token-row');e.target.value=values[mode][row.dataset.name];e.target.removeAttribute('aria-invalid')}});
$('token-list').addEventListener('click',e=>{if(e.target.closest('.token-reset')){const row=e.target.closest('.token-row'),d=definitions.find(d=>d[0]===row.dataset.name);update(d[0],d[mode==='light'?3:4]);renderTokens()}});
$('categories').addEventListener('click',e=>{const b=e.target.closest('button');if(b){category=b.dataset.category;$('search').value='';renderNav();renderTokens()}});$('search').addEventListener('input',renderTokens);
for(const m of ['light','dark'])$(m).onclick=()=>{mode=m;for(const n of ['light','dark'])$(n).classList.toggle('active',m===n);renderTokens();apply()};
$('undo').onclick=()=>{if(history.length){values=JSON.parse(history.pop());renderTokens();apply()}};$('reset').onclick=()=>{history.push(JSON.stringify(values));values=defaults();renderTokens();apply();toast('모든 토큰을 기본값으로 되돌렸습니다')};$('viewport').onclick=()=>{$('dashboard').classList.toggle('mobile');$('viewport').setAttribute('aria-pressed',$('dashboard').classList.contains('mobile'))};
function tokenSet(m){const root={};const add=(path,type,value)=>{const parts=path.split('.');let target=root;for(const part of parts.slice(0,-1))target=target[part]??=( {} );target[parts.at(-1)]={value,type}};for(const d of definitions)add(d[0],d[2],d[2]==='color'?values[m][d[0]]:d[2]==='fontWeights'?String(values[m][d[0]]):values[m][d[0]]+'px');for(const [path,ref]of [['color.bg.brand-solid',m==='light'?'color.palette.carrot-600':'color.palette.carrot-700'],['color.bg.brand-weak','color.palette.carrot-100'],['color.bg.layer-default',m==='light'?'color.palette.gray-00':'color.palette.gray-100'],['color.fg.neutral','color.palette.gray-1000'],['color.fg.neutral-muted','color.palette.gray-800'],['color.fg.positive','color.palette.green-700'],['color.fg.critical','color.palette.red-700'],['color.fg.informative','color.palette.blue-700']])add(path,'color','{'+ref+'}');return root}
function buildExport(){return {light:tokenSet('light'),dark:tokenSet('dark'),$themes:['light','dark'].map(m=>({id:'seed-studio-'+m,name:m==='light'?'Light':'Dark',selectedTokenSets:{[m]:'enabled'}})),$metadata:{tokenSetOrder:['light','dark']}}}
$('export').onclick=()=>{exportText=JSON.stringify(buildExport(),null,2);$('json-preview').textContent=exportText;$('export-dialog').showModal()};$('close-dialog').onclick=()=>$('export-dialog').close();$('export-dialog').addEventListener('click',e=>{if(e.target===$('export-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('copy-json').onclick=async()=>{try{await navigator.clipboard.writeText(exportText);toast('JSON을 복사했습니다')}catch{toast('복사할 수 없습니다. JSON을 다운로드하세요')}};$('download-json').onclick=()=>{const url=URL.createObjectURL(new Blob([exportText],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='seed-tokens-figma.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('토큰 JSON을 내보냈습니다')};
$('campaign').onclick=()=>toast('버튼 색상·간격·모서리를 토큰 패널에서 편집해보세요');$('tips').onclick=()=>toast('브랜드 배경과 본문 크기를 바꿔 카드의 변화를 확인하세요');document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('search').focus()}});renderNav();renderTokens();apply();
